import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import test from 'node:test';import {fileURLToPath} from 'node:url';
import { parseFrontMatter } from '../src/frontmatter.mjs';
const root=fileURLToPath(new URL('../../../',import.meta.url)),read=r=>fs.readFileSync(path.join(root,r),'utf8'),json=r=>JSON.parse(read(r));
const vocabularies={kinds:['decision','constraint','observation','question','proposal','direction','implementation','requirement','risk','goal','practice'],posture:['asserted','open','proposed','intended'],lifecycle:['active','historical','superseded','withdrawn'],relations:['supersedes','depends-on','supports','contradicts','refines','implements'],referenceRoles:['evidence','supporting','implementation','historical','example'],mapStatus:['draft','active','archived'],checkStatus:['draft','active','retired'],checkLevel:['required','advisory'],checkApplies:['atlas','map','area','point-anchor','point-context','resource','check','publication']};
test('packaged schemas are byte-identical',()=>{for(const n of ['common','atlas','map','point','check','publication','frontmatter','normalized','validation-result','fixture-manifest','check-evaluation'])assert.equal(read(`plugin/validator/schemas/${n}.schema.json`),read(`spec-source/schemas/${n}.schema.json`));assert.equal(read('workflows/meta-atlas-check/check-evaluation.schema.json'),read('spec-source/schemas/check-evaluation.schema.json'));});
test('vocabularies agree across schemas and prose',()=>{const point=json('spec-source/schemas/point.schema.json'),common=json('spec-source/schemas/common.schema.json'),map=json('spec-source/schemas/map.schema.json'),check=json('spec-source/schemas/check.schema.json'),anchor=point.$defs.anchor.properties;assert.deepEqual(anchor.kinds.items.anyOf[0].enum,vocabularies.kinds);assert.deepEqual(anchor.posture.enum,vocabularies.posture);assert.deepEqual(anchor.lifecycle.enum,vocabularies.lifecycle);assert.deepEqual(common.$defs.relation.properties.type.anyOf[0].enum,vocabularies.relations);assert.deepEqual(common.$defs.referenceRole.enum,vocabularies.referenceRoles);assert.deepEqual(map.properties.status.enum,vocabularies.mapStatus);assert.deepEqual(check.properties.status.enum,vocabularies.checkStatus);assert.deepEqual(check.properties.level.enum,vocabularies.checkLevel);assert.deepEqual(check.properties['applies-to'].items.enum,vocabularies.checkApplies);const prose=[read('spec-source/SPEC.md'),read('spec-source/spec/FORMAT.md'),read('spec-source/spec/CHECKS.md')].join('\n');for(const values of Object.values(vocabularies))for(const value of values)assert.ok(prose.includes(value),`Normative prose must contain ${value}.`);});
test('profile identifiers agree across implementation and prose',()=>{const validation=read('spec-source/spec/VALIDATION.md'),constants=read('plugin/validator/src/constants.mjs');for(const profile of ['neutral.atlas-validator.structural','neutral.atlas-validator.resolved']){assert.match(validation,new RegExp(profile.replaceAll('.','\\.'),'u'));assert.match(constants,new RegExp(profile.replaceAll('.','\\.'),'u'));}});
test('every emitted diagnostic is registered and has evidence',()=>{const validation=read('spec-source/spec/VALIDATION.md'),registered=new Set([...validation.matchAll(/`(atlas\.[a-z0-9.-]+)`/gu)].map(m=>m[1])),emitted=new Set();for(const file of fs.readdirSync(path.join(root,'plugin/validator/src')).filter(n=>n.endsWith('.mjs')))for(const m of read(`plugin/validator/src/${file}`).matchAll(/new Diagnostic\(['"](atlas\.[a-z0-9.-]+)['"]/gu))emitted.add(m[1]);assert.deepEqual([...emitted].filter(c=>!registered.has(c)).sort(),[]);const manifest=json('spec-source/examples/manifest.json'),fixtureCodes=new Set(manifest.fixtures.flatMap(f=>f.diagnostics)),unitOnly=new Set(['atlas.discovery.root-not-found','atlas.processing.io','atlas.reference.symlink','atlas.validation.unknown-profile','atlas.discovery.symbolic-link','atlas.check.duplicate-id','atlas.publication.duplicate-id']);assert.deepEqual([...registered].filter(c=>!fixtureCodes.has(c)&&!unitOnly.has(c)).sort(),[]);});
test('assurance matrix resolves every evidence link',()=>{const assurance=json('spec-source/assurance.json'),manifest=json('spec-source/examples/manifest.json'),fixturePaths=new Set(manifest.fixtures.map(f=>f.path)),human=read('ASSURANCE.md'),ownerFiles=new Set(['spec-source/SPEC.md','spec-source/spec/FORMAT.md','spec-source/spec/PROCESSING.md','spec-source/spec/VALIDATION.md','spec-source/spec/CHECKS.md','spec-source/spec/PUBLICATION.md','spec-source/spec/CONFORMANCE.md']),pointFiles=fs.readdirSync(path.join(root,'meta-atlas','maps'),{recursive:true}).filter(name=>name.includes(`${path.sep}points${path.sep}`)&&name.endsWith('.md')),pointIds=new Set(pointFiles.map(name=>parseFrontMatter(fs.readFileSync(path.join(root,'meta-atlas','maps',name),'utf8')).value?.id).filter(Boolean));assert.equal(assurance.format,1);assert.ok(Array.isArray(assurance.requirements)&&assurance.requirements.length>0);assert.equal(new Set(assurance.requirements.map(item=>item.id)).size,assurance.requirements.length);for(const item of assurance.requirements){assert.match(item.id,/^[a-z0-9]+(?:-[a-z0-9]+)*$/u);assert.ok(item.requirement.trim());for(const field of ['normative','schemas','fixtures','tests','metaAtlasPoints'])assert.ok(Array.isArray(item[field])&&item[field].length>0,`${item.id} requires ${field}.`);assert.ok(ownerFiles.has(item.owner),`${item.id} requires one current specification owner.`);assert.ok(item.normative.includes(item.owner),`${item.id} owner must be one of its normative links.`);for(const file of [...item.normative,...item.schemas,...item.tests])assert.ok(fs.statSync(path.join(root,file)).isFile(),`${item.id} references missing file ${file}.`);for(const fixture of item.fixtures)assert.ok(fixturePaths.has(fixture),`${item.id} references unknown fixture ${fixture}.`);for(const point of item.metaAtlasPoints)assert.ok(pointIds.has(point),`${item.id} references unknown Meta-Atlas Point ${point}.`);assert.ok(human.includes(`\`${item.id}\``),`ASSURANCE.md omits ${item.id}.`);}});
